// Holistic nutrition reference (research dataset 2026-10-18). Wording is "associated with" / "supports" — no treatment claims.
// Nutrient intake values are the U.S.-Canada DRI values as printed on NIH ODS pages; food amounts are copied from the NIH tables.

export type Strength = "strong" | "moderate" | "mixed" | "preliminary" | "not_supported" | "harm_signal";
export type Finding = { topic: string; finding: string; strength: Strength };
export type FoodSource = [food: string, amount: string, serving: string];
export type Nutrient = {
  id: string; name: string; kind: string; intake: string; upperLimit: string; functions: string;
  foods: FoodSource[]; atRisk: string; meds: string; research: Finding[]; cautions: string[]; sources: string[];
};
export type FoodEntry = {
  id: string; name: string; category: string; nutrients: [nutrient: string, amount: string, serving: string][];
  notes: string; cautions: string; sources: string[];
};
export type Herb = {
  id: string; name: string; wellEstablished: string | null; traditional: string[]; interactions: string; pregnancy: string;
  cautions: string[]; sources: string[];
};
export type Pairing = { pairing: string; detail: string; strength: Strength; sources: string[] };
export type CrossRef = { claim: string; evidence: string; agreement: string; note: string; sources: string[] };

export const STRENGTH_LABEL: Record<Strength, string> = {
  strong: "Strong",
  moderate: "Moderate",
  mixed: "Mixed",
  preliminary: "Preliminary",
  not_supported: "Not supported",
  harm_signal: "Higher risk in some groups",
};
export const STRENGTH_HELP: Record<Strength, string> = {
  strong: "established nutrient role or consistent trial evidence",
  moderate: "some trial evidence, limited or in specific groups",
  mixed: "trials and cohorts disagree",
  preliminary: "small, limited or observational only",
  not_supported: "trials do not show an effect",
  harm_signal: "trials found higher risk in some group",
};

const N = (id: string, name: string, kind: string, intake: string, upperLimit: string, functions: string, foods: FoodSource[], atRisk: string, meds: string, research: Finding[], cautions: string[], sources: string[]): Nutrient => ({ id, name, kind, intake, upperLimit, functions, foods, atRisk, meds, research, cautions, sources });
const R = (topic: string, finding: string, strength: Strength): Finding => ({ topic, finding, strength });
const F = (food: string, amount: string, serving: string): FoodSource => [food, amount, serving];

